## 7. Frontend JavaScript Client (`static/app.js`)

Once the protected dashboard page loads, this JavaScript module calls both `/api/user` (reading the Flask session profile) and `/api/orders` (triggering Flask to forward `session["access_token"]` to the downstream microservice). Both calls include `credentials: "same-origin"` so the browser transmits the `HttpOnly` session cookie.

```javascript
async function fetchProtectedEndpoint(endpoint) {
  const response = await fetch(endpoint, {
    method: "GET",
    credentials: "same-origin", // Includes the HttpOnly Flask session cookie
    headers: {
      "Accept": "application/json",
    },
  });

  // Redirect browser to Auth0 login flow if Flask session expired or is missing
  if (response.status === 401) {
    window.location.href = "/login";
    return null;
  }

  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.message || data.error || `HTTP ${response.status}`);
  }

  return data;
}

async function initializeDashboard() {
  try {
    // 1. Fetch OIDC user identity claims from Flask session
    const userResponse = await fetchProtectedEndpoint("/api/user");
    if (userResponse) {
      console.log("Authenticated User Profile:", userResponse.user);
    }

    // 2. Fetch protected business data from the downstream microservice via Flask BFF
    const ordersResponse = await fetchProtectedEndpoint("/api/orders");
    if (ordersResponse) {
      console.log("Downstream Microservice Data:", ordersResponse);
    }
  } catch (error) {
    console.error("Dashboard data fetch failed:", error.message);
  }
}

document.addEventListener("DOMContentLoaded", initializeDashboard);
```

